/* v4.9.405:增强 Markdown 渲染 —— 加代码块 / 表格 / 行内代码(原只有粗体+小标题)。
   安全:先 escHtml 转义，所有标签都是我们自己生成的,零注入风险。
   代码块用占位符保护,防止里面的 | / ** / ` 被后续规则误吃。 */
const rdMdToHtml = (s) => {
  let t = escHtml(s);
  const _pres = [];
  // ① 代码块 ```...``` → 先存起来,用占位符保护
  t = t.replace(/```[\s\S]*?```/g, function (m) {
    var inner = m.slice(3, -3).replace(/^\n/, '').replace(/\n$/, '');
    _pres.push('<pre style="background:rgba(127,127,127,.08);border:1px solid var(--rd-border);border-radius:6px;padding:8px 10px;margin:4px 0;overflow:auto;font-size:12px;line-height:1.5;white-space:pre-wrap"><code>' + inner + '</code></pre>');
    return '\x00P' + (_pres.length - 1) + '\x00';
  });
  // ② Markdown 表格 | 列1 | 列2 | (连续行,第二行必须是分隔行 |---|---|)
  t = t.replace(/((?:^\|.*\|\s*\n?)+)/gm, function (m) {
    var lines = m.trim().split('\n').filter(function (l) { return /^\|.*\|\s*$/.test(l); });
    if (lines.length < 2) return m;
    if (!/^\|[\s:|-]+\|\s*$/.test(lines[1])) return m;
    var cells = function (line) { return line.split('|').slice(1, -1).map(function (c) { return c.trim(); }); };
    var head = cells(lines[0]);
    var body = lines.slice(2).map(cells);
    var html = '<table style="border-collapse:collapse;margin:4px 0;font-size:12.5px;line-height:1.5;width:100%"><thead><tr>';
    head.forEach(function (h) { html += '<th style="border:1px solid var(--rd-border);background:rgba(47,111,79,.08);padding:4px 8px;text-align:left;font-weight:600;color:#2f6f4f">' + h + '</th>'; });
    html += '</tr></thead><tbody>';
    body.forEach(function (row, ri) {
      html += '<tr' + (ri % 2 ? ' style="background:rgba(127,127,127,.04)"' : '') + '>';
      row.forEach(function (c) { html += '<td style="border:1px solid var(--rd-border);padding:4px 8px">' + c + '</td>'; });
      html += '</tr>';
    });
    html += '</tbody></table>';
    return html;
  });
  // ③ 行内代码 `...`
  t = t.replace(/`([^`\n]+)`/g, '<code style="background:rgba(127,127,127,.12);border-radius:3px;padding:0 4px;font-size:12px;font-family:monospace">$1</code>');
  // ④ 小标题 ### → 加粗
  t = t.replace(/^[ \t]*#{1,4}[ \t]*(.+)$/gm, '<b>$1</b>');
  // ⑤ 粗体 **...**
  t = t.replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
  // ⑥ 恢复代码块
  t = t.replace(/\x00P(\d+)\x00/g, function (_, i) { return _pres[+i]; });
  return t;
};
