  const LN_STORE = (typeof globalThis !== 'undefined' && globalThis.LN_STORE) || null;
  const DB_NAME = 'esjzone_epub_cache';
  const DB_VERSION = 1;
  let dbPromise = null;
  function openDB() {
    if (LN_STORE) return LN_STORE.open();
    if (dbPromise) return dbPromise;
    dbPromise = new Promise((resolve, reject) => {
      const req = indexedDB.open(DB_NAME, DB_VERSION);
      req.onupgradeneeded = (e) => {
        const db = e.target.result;
        if (!db.objectStoreNames.contains('meta')) db.createObjectStore('meta', { keyPath: 'novelId' });
        if (!db.objectStoreNames.contains('chapters')) db.createObjectStore('chapters', { keyPath: 'key' });
        if (!db.objectStoreNames.contains('images')) db.createObjectStore('images', { keyPath: 'url' });
        if (!db.objectStoreNames.contains('settings')) db.createObjectStore('settings', { keyPath: 'key' });
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error);
    });
    return dbPromise;
  }
  function idbPut(store, val) {
    if (LN_STORE) return LN_STORE.put(store, val);
    return openDB().then(db => new Promise((res, rej) => {
      const tx = db.transaction(store, 'readwrite');
      tx.objectStore(store).put(val);
      tx.oncomplete = () => res(val);
      tx.onerror = () => rej(tx.error);
    }));
  }
  function idbGet(store, key) {
    if (LN_STORE) return LN_STORE.get(store, key);
    return openDB().then(db => new Promise((res, rej) => {
      const rq = db.transaction(store, 'readonly').objectStore(store).get(key);
      rq.onsuccess = () => res(rq.result || null);
      rq.onerror = () => rej(rq.error);
    }));
  }
  /* v4.9.168-扩展移植:批量删 —— 一次 IPC 删多个键。
     原来是"一个键一个来回"(删一本 70 章的书 = 70 个消息来回,实测 1~2 秒),现在一个来回。
      keys 必须是库内已带前缀的键(调用方从 idbAll 拿到的记录里取 c.key / im.url,与单条 idbDel 同源)。 */
  async function idbDelMany(store, keys) {
    const list = (Array.isArray(keys) ? keys : []).filter((k) => k != null);
    if (!list.length) return 0;
    if (LN_STORE && LN_STORE.delMany) return LN_STORE.delMany(store, list);
    for (const k of list) await idbDel(store, k);   // 没桥(油猴环境)时退回逐条,行为一致
    return list.length;
  }
  function idbDel(store, key) {
    if (LN_STORE) return LN_STORE.del(store, key);
    return openDB().then(db => new Promise((res, rej) => {
      const tx = db.transaction(store, 'readwrite');
      tx.objectStore(store).delete(key);
      tx.oncomplete = () => res();
      tx.onerror = () => rej(tx.error);
    }));
  }
  function idbClear(store) {
    if (LN_STORE) return LN_STORE.clear(store);
    return openDB().then(db => new Promise((res, rej) => {
      const tx = db.transaction(store, 'readwrite');
      tx.objectStore(store).clear();
      tx.oncomplete = () => res();
      tx.onerror = () => rej(tx.error);
    }));
  }
  function idbAll(store) {
    if (LN_STORE) return LN_STORE.all(store);
    return openDB().then(db => new Promise((res, rej) => {
      const rq = db.transaction(store, 'readonly').objectStore(store).getAll();
      rq.onsuccess = () => res(rq.result || []);
      rq.onerror = () => rej(rq.error);
    }));
  }
  function idbCount(store) {
    if (LN_STORE) return LN_STORE.count(store);
    return openDB().then(db => new Promise((res, rej) => {
      const rq = db.transaction(store, 'readonly').objectStore(store).count();
      rq.onsuccess = () => res(rq.result);
      rq.onerror = () => rej(rq.error);
    }));
  }
  // v3.4.2:只判断某个 key 是否存在(用 count(key),不取 value)——
  //   模型记录是几十到上百 MB 的 ArrayBuffer,若为了显示「缓存已就绪」而 idbGet 整条,
  //   每次打开设置都要把整个模型反序列化进内存,纯属浪费。
  function idbHas(store, key) {
    if (LN_STORE) return LN_STORE.has(store, key);
    return openDB().then(db => new Promise((res, rej) => {
      const rq = db.transaction(store, 'readonly').objectStore(store).count(key);
      rq.onsuccess = () => res(!!rq.result);
      rq.onerror = () => rej(rq.error);
    }));
  }

  /* ============ 共享:网络请求 ============ */
  function gmGet(url, opts) {
    opts = opts || {};
    return new Promise((resolve, reject) => {
      try {
        GM_xmlhttpRequest({
          url: url,
          method: 'GET',
          timeout: opts.timeout || 45000,
          responseType: opts.responseType || 'text',
          headers: Object.assign({ Referer: location.origin + '/' }, opts.headers || {}),
          onload: r => resolve(r),
          /* v4.9.169-扩展移植:原来这里把任何失败都写死成「网络错误」——扩展刚被 ↻ 过、
             老页面的内容脚本已经失联时,跨域请求必然失败,而它显示成「网络错误」,把排查方向
             整个带偏(以为要开代理)。改成保留真实错误消息(桥给的是「扩展刚被重新加载过…」)。 */
          onerror: (e) => reject((e && e.message) ? e : new Error('网络错误')),
          ontimeout: () => reject(new Error('请求超时')),
          onprogress: opts.onprogress || null  // v3.4.8:下载进度回调(模型下载进度条)
        });
      } catch (e) { reject(e); }
    });
  }
  // v3.5.14:网络层失败/超时自动重试(最多 3 轮,退避 1s/3s)——解决章节请求挂起导致「无响应/停止无效/漏抓」;
  //   每轮 = GM_xhr(45s 超时) + 同源 fetch 兜底(45s 超时,AbortController,修复旧版 fetch 无超时会无限挂起);
  //   拿到 HTTP 非 2xx/空响应属确定失败,不再重试(避免对 404 等白等)
  let last429At = 0; // 全局最近一次 429 时间戳——限流站点(wenku8)的串行链据此加冷却
  async function httpText(url) {
    // 从 ArrayBuffer + 响应头/页面 meta 检测编码并解码(支持 GBK 等非 UTF-8 站点)
    const decodeBuf = (buf, contentTypeHeader) => {
      const ct = contentTypeHeader || '';
      let charset = '';
      const m = ct.match(/charset=([\w-]+)/i);
      if (m) charset = m[1].toLowerCase();
      if (!charset && buf) {
        const head = new TextDecoder('utf-8').decode(buf.slice(0, 2048));
        const mm = head.match(/<meta[^>]+charset=["']?([\w-]+)/i) || head.match(/charset=([\w-]+)/i);
        if (mm) charset = mm[1].toLowerCase();
      }
      if (charset && charset !== 'utf-8' && charset !== 'utf8') {
        try { return new TextDecoder(charset).decode(buf); } catch (e) {}
      }
      return new TextDecoder('utf-8').decode(buf);
    };
    for (let attempt = 1; attempt <= 3; attempt++) {
      let netErr = false;
      let rateLimited = false;
      // v4.0.1:优先用 fetch(arraybuffer+编码检测),已验证可正确处理 GBK;gmGet 的 arraybuffer 模式在部分油猴版本可能返回乱码
      try {
        const ac = new AbortController();
        const to = setTimeout(() => ac.abort(), 45000);
        try {
          const r = await fetch(url, { credentials: 'include', signal: ac.signal });
          if (r.status === 429) { rateLimited = true; last429At = Date.now(); throw new Error('429 限流'); }
          if (r.ok) {
            const buf = await r.arrayBuffer();
            return decodeBuf(buf, r.headers.get('content-type') || '');
          }
        } finally { clearTimeout(to); }
      } catch (e) { netErr = true; if (e.message === '429 限流') rateLimited = true; }
      // fetch 失败(跨域/网络)时 fallback 到 GM_xmlhttpRequest
      if (!rateLimited) {
        try {
          const r = await gmGet(url, { responseType: 'arraybuffer' });
          if (r.status === 429) { rateLimited = true; last429At = Date.now(); }
          else if (r.status >= 200 && r.status < 300 && r.response) {
            return decodeBuf(r.response, r.responseHeaders || '');
          }
        } catch (e) { netErr = true; }
      }
      if (!netErr && !rateLimited) return null; // 有响应但非 2xx/空 → 确定失败,不再重试
      // 429 限流:退避更长时间(5s/10s),避免持续触发封禁
      if (attempt < 3) await sleep(rateLimited ? (attempt === 1 ? 5000 : 10000) : (attempt === 1 ? 1000 : 3000));
    }
    return null;
  }
  async function httpBlob(url) {
    // v3.5.14:同 httpText —— 网络层失败/超时自动重试(最多 3 轮,退避 1s/3s);确定失败(非 2xx/空)不重试
    for (let attempt = 1; attempt <= 3; attempt++) {
      let netErr = false;
      try {
        const r = await gmGet(url, { responseType: 'blob' });
        if (r.status >= 200 && r.status < 300 && r.response && r.response.size) {
          return { blob: r.response, contentType: r.response.type || '' };
        }
      } catch (e) { netErr = true; }
      try {
        const ac = new AbortController();
        const to = setTimeout(() => ac.abort(), 45000);
        try {
          const r = await fetch(url, { credentials: 'include', signal: ac.signal });
          if (r.ok) {
            const b = await r.blob();
            return { blob: b, contentType: b.type || '' };
          }
        } finally { clearTimeout(to); }
      } catch (e) { netErr = true; }
      // v3.4.11:第三级兜底用普通 XHR —— 实测 bkimg(百度)等图床对 fetch(CORS 预检)直接 "Failed to fetch",
      //   但同页内 XHR blob 能拿到 200/图片(服务端放行);GM 与 fetch 都失败时靠这一级,封面不再莫名缺失。
      try {
        const b = await new Promise((res, rej) => {
          const xhr = new XMLHttpRequest();
          xhr.open('GET', url, true);
          xhr.timeout = 45000;
          xhr.responseType = 'blob';
          xhr.onload = () => (xhr.status >= 200 && xhr.status < 300 && xhr.response ? res(xhr.response) : rej(new Error('XHR HTTP ' + xhr.status)));
          xhr.onerror = () => rej(new Error('XHR 网络错误'));
          xhr.ontimeout = () => rej(new Error('XHR 超时'));
          xhr.send();
        });
        if (b && b.size) return { blob: b, contentType: b.type || '' };
      } catch (e) { netErr = true; }
      if (!netErr) return null; // 有响应但非 2xx/空 → 确定失败,不再重试
      if (attempt < 3) await sleep(attempt === 1 ? 1000 : 3000);
    }
    return null;
  }

  /* ============ 共享:XML 序列化 ============ */
  const VOID_TAGS = new Set(['br', 'img', 'hr', 'meta', 'link', 'input', 'source', 'wbr', 'area', 'base', 'col', 'embed', 'param', 'track']);
  const SAFE_ATTRS = new Set(['id', 'class', 'style', 'title', 'align', 'width', 'height', 'alt', 'src', 'href', 'target', 'colspan', 'rowspan', 'bgcolor', 'color', 'face', 'size', 'start', 'dir', 'lang']);
  /* v4.9.241(§4.1 第 5 条):从块的 html 里抽出"段落级属性"(白名单内,如 style/class)——
     手改 / 翻译回填时"只换文本、不洗样式"。三处共用:rdReplaceBlock(润色·替换本段)、
     editorHtmlToBlocks(章节编辑器纯文本块)、numberedTextToBlocks(AI 整章回填)。 */
  const blkAttrsOf = (html, tag) => {
    try {
      const m = String(html || '').match(new RegExp('^<' + String(tag || 'p').replace(/[^a-zA-Z0-9]/g, '') + '\\b([^>]*)>', 'i'));
      if (!m) return '';
      const re = /([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*("([^"]*)"|'([^']*)')/g;
      let out = '', mm;
      while ((mm = re.exec(m[1]))) {
        const n = String(mm[1]).toLowerCase();
        if (!SAFE_ATTRS.has(n)) continue;
        out += ' ' + n + '="' + escAttr(mm[3] != null ? mm[3] : (mm[4] || '')) + '"';
      }
      return out;
    } catch (e) { return ''; }
  };

  function resolveImgSrc(node) {
    const srcset = node.getAttribute('srcset');
    if (srcset) {
      let best = '', bestW = 0;
      for (const part of srcset.split(',')) {
        const bits = part.trim().split(/\s+/);
        const w = parseInt((bits[1] || '').replace(/\D/g, ''), 10) || 0;
        if (w > bestW) { bestW = w; best = bits[0]; }
      }
      if (best) return best;
    }
    return node.getAttribute('data-src') || node.getAttribute('src') || '';
  }

  // 把 DOM 元素序列化为合法 XHTML；img 的远程地址替换为 [[IMG:k]] 占位符并登记到 imgMap(url→序号)
  function serializeToXHTML(root, imgMap) {
    let out = '';
    function walk(node) {
      if (node.nodeType === Node.TEXT_NODE) { out += escHtml(node.nodeValue); return; }
      if (node.nodeType !== Node.ELEMENT_NODE) return;
      const tag = node.tagName.toLowerCase();
      if (tag === 'script' || tag === 'style' || tag === 'iframe' || tag === 'noscript' || tag === 'svg' || tag === 'ins') return;
      if (tag === 'img') {
        const src = normUrl(resolveImgSrc(node));
        const attrs = [];
        if (/^data:/i.test(src)) {
          attrs.push('src="' + escAttr(src) + '"');
        } else if (src) {
          if (!imgMap.has(src)) imgMap.set(src, imgMap.size);
          attrs.push('src="[[IMG:' + imgMap.get(src) + ']]"');
        } else {
          attrs.push('src=""');
        }
        const alt = node.getAttribute('alt');
        if (alt) attrs.push('alt="' + escAttr(alt) + '"');
        for (const a of ['width', 'height', 'style', 'class', 'title', 'align', 'id']) {
          const v = node.getAttribute(a);
          if (v) attrs.push(a + '="' + escAttr(v) + '"');
        }
        out += '<img ' + attrs.join(' ') + '/>';
        return;
      }
      const attrs = [];
      for (const attr of node.attributes) {
        const name = attr.name.toLowerCase();
        if (!SAFE_ATTRS.has(name)) continue;
        let val = attr.value;
        if (name === 'href' && /^\s*javascript:/i.test(val)) continue;
        if (name === 'src') {
          const s = normUrl(resolveImgSrc(node));
          if (/^data:/i.test(s)) { val = s; }
          else if (s) { if (!imgMap.has(s)) imgMap.set(s, imgMap.size); val = '[[IMG:' + imgMap.get(s) + ']]'; }
          else continue;
        }
        attrs.push(name + '="' + escAttr(val) + '"');
      }
      if (VOID_TAGS.has(tag)) { out += '<' + tag + (attrs.length ? ' ' + attrs.join(' ') : '') + '/>'; return; }
      out += '<' + tag + (attrs.length ? ' ' + attrs.join(' ') : '') + '>';
      for (let i = 0; i < node.childNodes.length; i++) walk(node.childNodes[i]);
      out += '</' + tag + '>';
    }
    walk(root);
    return out;
  }

  // 将单个 DOM 元素转为一个或多个 XHTML 块;
  // ESJ 等站点常用一个 <p> 包裹全文、以 <br> 分行,
  // 按 <br> 拆成多个同标签块,使每段都有独立的缩进与间距。
  function elementToBlocks(el, tag, imgMap) {
    if (tag === 'br' || tag === 'hr') return [{ type: tag, html: '<' + tag + '/>' }];
    if (tag === 'img') return [{ type: tag, html: serializeToXHTML(el, imgMap) }];
    if (el.children.length === 0) {
      const t = (el.innerText || '').trim();
      if (!t) return [];
      /* v4.9.241(§4.1 第 5 条):纯文本块也要保留外层属性(白名单属性,如 style/class)——
         否则章节编辑器改一个字,该章所有"带 style 的纯文本段"(装饰页那种)会一起掉样式。 */
      let _at = '';
      try { for (const _a of el.attributes) { const _n = String(_a.name || '').toLowerCase(); if (!SAFE_ATTRS.has(_n)) continue; _at += ' ' + _n + '="' + escAttr(_a.value) + '"'; } } catch (e) {}
      return [{ type: tag, html: '<' + tag + _at + '>' + escHtml(t) + '</' + tag + '>' }];
    }
    const fullHtml = serializeToXHTML(el, imgMap).trim();
    const hasDirectBr = Array.from(el.children).some(c => c.tagName.toLowerCase() === 'br');
    if ((tag === 'p' || tag === 'div') && hasDirectBr && /<br\s*\/?>/i.test(fullHtml)) {
      const m = fullHtml.match(new RegExp('^<' + tag + '([^>]*)>([\\s\\S]*)</' + tag + '>$', 'i'));
      if (m) {
        // 只继承"对齐"信息(text-align / align),其余属性不复制——避免把整段样式平铺到每个碎片
        const attrStr = m[1] || '';
        let alignExtra = '';
        const sm = attrStr.match(/\bstyle\s*=\s*("([^"]*)"|'([^']*)')/i);
        if (sm) {
          const css = sm[2] != null ? sm[2] : (sm[3] || '');
          const at = css.split(';').map(s => s.trim()).filter(s => /^text-align\s*:/i.test(s)).join(';');
          if (at) alignExtra += ' style="' + escAttr(at) + '"';
        }
        const am = attrStr.match(/\balign\s*=\s*("([^"]*)"|'([^']*)')/i);
        if (am) alignExtra += ' align="' + escAttr(am[2] != null ? am[2] : (am[3] || '')) + '"';
        const out = [];
        for (let seg of m[2].split(/<br\s*\/?>/i)) {
          seg = seg.trim();
          if (seg) out.push({ type: tag, html: '<' + tag + alignExtra + '>' + seg + '</' + tag + '>' });
        }
        if (out.length) return out;
        return []; // 仅含 <br> 的空块,跳过
      }
    }
    return [{ type: tag, html: fullHtml }];
  }

  /* ============ ESJ Zone 适配器 ============ */
  function pageTypeESJ() {
    if (/\/detail\/\d+\.html/.test(location.pathname)) return 'detail';
    if (/\/forum\/\d+\/\d+\/?$/.test(location.pathname)) {
      // 小说论坛页(/forum/{分类id}/{小说id}/,末尾斜杠,免登录可访问):有书籍详情/章节列表即按详情页处理
      if ($('.book-detail') || $('#chapterList') || $('#integration')) return 'detail';
      return 'other';
    }
    if (/\/forum\/\d+\/\d+\.html/.test(location.pathname)) {
      // 章节页有时也展示完整详情(如权限不足时),按 DOM 判定
      if ($('.book-detail') && $('#chapterList')) return 'detail';
      return 'chapter';
    }
    return 'other';
  }
  function pageNovelIdESJ() {
    // /forum/{分类id}/{小说id}/(小说论坛页,末尾斜杠)→ 第二段才是小说 id
    let m = location.pathname.match(/\/forum\/\d+\/(\d+)\/?$/);
    if (m) return m[1];
    // 其余(/detail/{小说id}.html、/forum/{小说id}/{章节id}.html)→ 第一段为小说 id
    m = location.pathname.match(/^\/(?:detail|forum)\/(\d+)/);
    return m ? m[1] : null;
  }
  function parseChapterDoc(doc, pageUrl, skipCipherCheck) {
    const m = String(pageUrl).match(/\/forum\/(\d+)\/(\d+)\.html/);
    if (!m) return null;
    const novelId = m[1], chapterId = m[2];
    const h2 = $('h2', doc);
    const title = h2 ? (h2.innerText || '').trim() : '';
    // 密码锁章节:正文容器(.forum-content.mt-3)仍然存在,#oops 密码输入框在它内部;
    // 必须最先判断,否则会被当成正常章节解析出密码表单垃圾内容
    if ($('#oops', doc) && $('#pw', doc)) {
      return { locked: true, pw: true, novelId: novelId, chapterId: chapterId, title: title };
    }
    const content = $('.forum-content.mt-3', doc);
    if (!content) return null;
    // 结构性检测(零误判):已解锁的密码章,正文开头带站点字体加密的 <link data:text/css,@font-face>;
    // 会话已解锁时页面没有密码框,只能靠这个标记识别,否则会存成无字体的乱码
    if (!skipCipherCheck) {
      const link = content.querySelector('link[href^="data:text/css"][rel="stylesheet"]');
      if (link) {
        try {
          if (/@font-face/i.test(decodeURIComponent(link.getAttribute('href') || ''))) {
            return { locked: true, ciphered: true, novelId: novelId, chapterId: chapterId, title: title };
          }
        } catch (e) {}
      }
    }
    const imgMap = new Map();
    const blocks = [];
    // 遍历 childNodes(含直接文本节点):部分章节正文直接写在容器文本节点里,子元素只是空壳 <p>/<br>
    for (const node of content.childNodes) {
      if (node.nodeType === Node.TEXT_NODE) {
        const t = (node.nodeValue || '').trim();
        if (t) blocks.push({ type: 'p', html: '<p>' + escHtml(t) + '</p>' });
        continue;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) continue;
      const tag = node.tagName.toLowerCase();
      if (tag === 'br' || tag === 'hr') continue; // 独立 br/hr 只是分行装饰,忽略
      for (const b of elementToBlocks(node, tag, imgMap)) {
        if (b.html && b.html.trim()) blocks.push({ type: b.type, html: b.html.trim() });
      }
    }
    const imgUrls = imgMapToUrls(imgMap);
    const textLen = (content.innerText || '').trim().length;
    return { novelId, chapterId, title, blocks, imgUrls, textLen };
  }
  function novelTitleFromDoc(doc) {
    // 1) 优先:面包屑里指向小说论坛首页的链接
    for (const a of $$('.breadcrumb a, .breadcrumb-item a', doc)) {
      if (/\/forum\/\d+\/\d+\/$/.test(a.getAttribute('href') || '')) {
        const t = (a.innerText || '').trim();
        if (t) return t;
      }
    }
    // 2) 页面标题前缀 "小说名 - 章节名 - ESJ Zone"
    const dt = (document.title || '').split(' - ')[0].trim();
    if (dt && dt.length > 1 && !/^(ESJ Zone|輕小說|論壇|Home)$/i.test(dt)) return dt;
    // 3) 面包屑最后一个
    const crumbs = $$('.breadcrumb a', doc);
    if (crumbs.length) {
      const t = (crumbs[crumbs.length - 1].innerText || '').trim();
      if (t && !/^(Home|論壇|輕小說)$/i.test(t)) return t;
    }
    const h2 = $('h2', doc);
    if (h2) return (h2.innerText || '').trim();
    return '';
  }
  function pickCoverEl(doc, h2) {
    const bad = /nophoto|logo|avatar|icon/i;
    const clean = (el) => { if (el && bad.test(el.getAttribute('src') || '')) return null; return el; };
    let el = clean($('img[src*="cover"]', doc));
    if (!el) el = clean($('.book-cover img, .cover img, .product-gallery img', doc));
    if (!el && h2) {
      // 兜底:标题所在行(book-detail)左侧列的第一张图
      const bd = h2.closest('.book-detail') || h2.parentElement;
      const row = bd ? bd.parentElement : null;
      const prev = row ? (bd.previousElementSibling || row.firstElementChild) : null;
      if (prev) el = clean($('img', prev));
    }
    return el || null;
  }
  // 从页面(详情页/章节页)面包屑锚点提取小说分类 id:链接形如 /forum/{分类id}/{小说id}/
  // (章节链接是 /forum/{小说id}/{章节id}.html,第二段带 .html,不会误匹配)
  function esjForumCatIdFromDoc(doc, novelId) {
    try {
      const re = new RegExp('/forum/(\\d+)/' + novelId + '/?(?:[?#]|$)');
      for (const a of $$('a[href*="/forum/"]', doc)) {
        const cm = String(a.getAttribute('href') || '').match(re);
        if (cm) return cm[1];
      }
    } catch (e) {}
    return '';
  }
  function parseDetailDoc(doc, pageUrl) {
    const pu = String(pageUrl || '');
    let novelId = '', forumCatId = '';
    let m = pu.match(/\/detail\/(\d+)\.html/);
    if (m) {
      novelId = m[1];
    } else {
      // 小说论坛页 /forum/{分类id}/{小说id}/(末尾斜杠,免登录可访问):第二段是小说 id
      m = pu.match(/\/forum\/(\d+)\/(\d+)\/?(?:[?#]|$)/);
      if (m) { forumCatId = m[1]; novelId = m[2]; }
      else {
        // 章节页等情况:退化为第一个 forum 数字 id
        m = pu.match(/\/forum\/(\d+)/);
        if (m) novelId = m[1];
      }
    }
    if (!novelId) {
      const fl = $('a[href*="/forum/"]', doc);
      if (fl) {
        const lm = String(fl.getAttribute('href') || '').match(/\/forum\/(\d+)/);
        if (lm) novelId = lm[1];
      }
    }
    if (!novelId) return null;
    // URL 里没带分类 id 时(如 /detail/ 页),从面包屑锚点补提
    if (!forumCatId) forumCatId = esjForumCatIdFromDoc(doc, novelId);
    const h2 = $('h2', doc);
    const title = h2 ? (h2.innerText || '').trim() : novelTitleFromDoc(doc);
    const coverEl = pickCoverEl(doc, h2);
    const coverUrl = coverEl ? normUrl(coverEl.getAttribute('src') || coverEl.currentSrc) : '';
    let author = '', category = '';
    const detailUl = $('.book-detail', doc);
    const liScope = detailUl ? $$('li', detailUl) : $$('li', doc);
    for (const li of liScope) {
      const t = (li.innerText || '').trim();
      let mm;
      if (!author && (mm = t.match(/^作者\s*[:：]\s*(.+)$/))) {
        const a = $('a', li);
        author = a ? (a.innerText || '').trim() : mm[1].trim();
      } else if (!category && (mm = t.match(/^(?:類型|类型)\s*[:：]\s*(.+)$/))) {
        category = mm[1].trim();
      }
      if (author && category) break;
    }
    // 标签
    let tags = '';
    const tagAs = $$('.widget-tags a.tag, .widget-tags a, .show-tag a', doc);
    if (tagAs.length) tags = tagAs.map(a => (a.innerText || '').trim()).filter(Boolean).join(' ');
    // 简介
    let description = '';
    const descEl = $('.description', doc);
    if (descEl) description = (descEl.innerText || '').trim();
    const sections = [];
    const integration = $('#integration', doc);
    const linkSel = 'a[href*="/forum/' + novelId + '/"]';
    if (integration) {
      // 找到承载 <details> 的直接容器(可能本身就是 details,也可能是其唯一子容器,如 #chapterList)
      let detailsList = $$(':scope > details', integration);
      if (!detailsList.length) {
        for (const el of integration.children) {
          const dd = $$(':scope > details', el);
          if (dd.length) { detailsList = dd; break; }
        }
      }
      for (const d of detailsList) {
        const sum = $('summary', d);
        const section = sum ? (sum.innerText || '').trim() : '';
        const chapters = [];
        for (const a of $$(linkSel, d)) {
          const cm = String(a.getAttribute('href')).match(/\/forum\/\d+\/(\d+)\.html/);
          if (!cm) continue;
          const ct = (a.getAttribute('data-title') || a.innerText || '').trim();
          chapters.push({ id: cm[1], title: ct });
        }
        if (chapters.length) sections.push({ section, chapters });
      }
    }
    if (!sections.length) {
      // 兜底:整页收集章节链接
      const chapters = [];
      for (const a of $$(linkSel, doc)) {
        const cm = String(a.getAttribute('href')).match(/\/forum\/\d+\/(\d+)\.html/);
        if (!cm) continue;
        chapters.push({ id: cm[1], title: (a.getAttribute('data-title') || a.innerText || '').trim() });
      }
      if (chapters.length) sections.push({ section: '', chapters });
    }
    dedupeChaptersBySection(sections);
    // 收集 #integration 中不在任何 details 内的独立链接(如排在章节列表末尾的「完结后记」「译者感言」)
    if (integration) {
      const extra = [];
      const existingIds = new Set();
      for (const s of sections) for (const c of s.chapters) existingIds.add(c.id);
      for (const a of $$(linkSel, integration)) {
        if (a.closest('details')) continue;
        const cm = String(a.getAttribute('href')).match(/\/forum\/\d+\/(\d+)\.html/);
        if (!cm || existingIds.has(cm[1])) continue;
        existingIds.add(cm[1]);
        extra.push({ id: cm[1], title: (a.getAttribute('data-title') || a.innerText || '').trim() });
      }
      if (extra.length) sections.push({ section: '其他', chapters: extra });
    }
    return { novelId, title, author, coverUrl, tags, description, category, forumCatId, sections, fetchedAt: Date.now() };
  }
  async function esjParseChapterFromWeb(novelId, ch) {
    const url = location.origin + '/forum/' + novelId + '/' + ch.id + '.html';
    let html = await httpText(url);
    if (!html && /esjzone\.cc/.test(location.host)) html = await httpText('https://www.esjzone.one/forum/' + novelId + '/' + ch.id + '.html');
    if (!html && /esjzone\.one/.test(location.host)) html = await httpText('https://www.esjzone.cc/forum/' + novelId + '/' + ch.id + '.html');
    if (!html) return null;
    const doc = new DOMParser().parseFromString(html, 'text/html');
    return parseChapterDoc(doc, url);
  }
  async function doUpdateESJ(refetchAll) {
    stopFlag = false;
    if (pageTypeESJ() !== 'detail') { log('请先打开小说详情页(/detail/数字.html 或 /forum/分类id/小说id/)'); return; }
    const fresh = parseDetailDoc(document, location.href);
    if (!fresh) { log('详情页解析失败'); return; }
    // 合并而非覆盖:保留已存 meta 的持久字段(pwChapters 密码章标记等),仅更新从页面解析出的目录/标题
    const storedMeta = await getMeta(fresh.novelId).catch(() => null);
    const meta = Object.assign({}, storedMeta || {}, fresh, { novelId: fresh.novelId });
    await saveMeta(meta);
    // v3.4.11:详情解析成功即把封面字节预下载进缓存(幂等;失败不影响抓取)
    try { prefetchBookCover(meta, false); } catch (e) {}
    await runFetchQueue(meta, refetchAll);
  }
  async function fetchCurrentChapterESJ() {
    stopFlag = false;
    if (pageTypeESJ() !== 'chapter') { log('当前页面不是章节页'); return; }
    const parsed = parseChapterDoc(document, location.href);
    if (!parsed) { log('未找到正文容器'); return; }
    let section = '';
    const meta = await ensureMeta(parsed.novelId, novelTitleFromDoc(document));
    // 章节页面包屑带小说分类 id,顺带回填(旧缓存/单章抓取也能拿到免登录详情页地址)
    if (!meta.forumCatId) {
      const catId = esjForumCatIdFromDoc(document, parsed.novelId);
      if (catId) { meta.forumCatId = catId; await saveMeta(meta); }
    }
    for (const s of meta.sections || []) {
      for (const c of s.chapters) if (c.id === parsed.chapterId) section = s.section;
    }
    // 密码锁章节:当前页正文为空(含 #oops 密码框),标记到 meta.pwChapters 后跳过,不缓存
    if (parsed.locked) {
      log('🔒 本章为密码章,未缓存(可在章节管理/选章抓取中识别,或用「替换」手动填写内容)');
      try {
        const m2 = await getMeta(parsed.novelId);
        if (m2) {
          m2.pwChapters = m2.pwChapters || {};
          m2.pwChapters[String(parsed.chapterId)] = { title: parsed.title || '', section: section || '', at: Date.now(), kind: parsed.ciphered ? 'cipher' : 'pw' };
          await saveMeta(m2);
        }
      } catch (e) {}
      return;
    }
    log('抓取本章: ' + parsed.title);
    try {
      const rec = await fetchAndStoreChapter(parsed.novelId, { id: parsed.chapterId, title: parsed.title }, section, parsed, location.href);
      unmarkChapterFailed(parsed.novelId, parsed.chapterId);
      await unmarkPasswordChapter(parsed.novelId, parsed.chapterId); // 已解锁成功抓取,清残留的密码章标记
      log('  ✓ 已缓存, 图片 ' + rec.imgOk + ' 张' + (rec.imgFail ? ', ' + rec.imgFail + ' 张失败' : ''));
    } catch (e) {
      markChapterFailed(parsed.novelId, { id: parsed.chapterId, title: parsed.title }, e && e.message);
      log('  ✗ 失败: ' + e.message);
    }
    await refreshStatus();
    reconcileLocalBookIndex(); // 更新跨站书籍索引(失败静默,不影响抓取)
  }

  /* ============ ESJ 密码章节(专属):仅识别与标记 ============
   * 锁章页正文为空,页面含 #oops 密码输入框;已解锁的章正文带站点字体加密 link。
   * 识别后由抓取层标记(meta.pwChapters)并跳过缓存;密码章可用「替换」手动填写成普通章。 */
  function esjPwError(kind) { const e = new Error('该章需要密码'); e.code = 'ESJ_PW'; if (kind) e.pwKind = kind; return e; }

  /* ============ 哔哩轻小说适配器 ============ */
  function pageTypeLINOVELIB() {
    const p = location.pathname;
    if (/\/novel\/\d+\/catalog$/.test(p) || /\/novel\/\d+\.html$/.test(p)) return 'detail';
    if (/\/novel\/\d+\/\d+\.html$/.test(p)) return 'chapter';
    return 'other';
  }
  function pageNovelIdLINOVELIB() {
    const m = location.pathname.match(/\/novel\/(\d+)/);
    return m ? m[1] : null;
  }
  function linovelibNovelTitle(doc) {
    // 面包屑:当前位置：首页 > ... > 小说名(/novel/数字.html)
    const links = $$('a[href*="/novel/"]', doc);
    for (let i = links.length - 1; i >= 0; i--) {
      const href = links[i].getAttribute('href') || '';
      if (/\/novel\/\d+\.html$/.test(href)) return (links[i].innerText || '').trim();
    }
    return '';
  }
  function linovelibParseCatalog(doc, novelId) {
    const sections = [];
    const linkSel = 'a[href*="/novel/' + novelId + '/"]';
    for (const vol of $$('div.volume', doc)) {
      const h2 = $('.volume-info h2, .volume-info a', vol);
      const section = h2 ? (h2.innerText || '').trim() : '';
      const chapters = [];
      for (const a of $$(linkSel, vol)) {
        const cm = String(a.getAttribute('href')).match(/\/novel\/\d+\/(\d+)\.html/);
        if (!cm) continue;
        const t = (a.innerText || '').trim();
        if (!t) continue;
        chapters.push({ id: cm[1], title: t });
      }
      if (chapters.length) sections.push({ section, chapters });
    }
    return dedupeChaptersBySection(sections);
  }
  // 从哔哩轻小说页面提取书籍元信息(作者/标签/简介等),多策略兜底
  function linovelibExtractBookInfo(doc) {
    const info = { author: '', tags: '', description: '', status: '', category: '' };
    const meta = (sel) => {
      const el = $(sel, doc);
      return el ? (el.getAttribute('content') || '').trim() : '';
    };
    // 1. <meta property="og:novel:author"> / <meta name="author">
    info.author = meta('meta[property="og:novel:author"]') || meta('meta[name="author"]');
    // 2. 详情页 .book-author .au-name 中第一个 a[href*="/authorarticle/"]
    if (!info.author) {
      const auBox = $('.book-author .au-name', doc);
      const auA = auBox ? $('a[href*="/authorarticle/"]', auBox) : null;
      if (auA) info.author = (auA.innerText || '').trim();
    }
    // 3. 目录页 .book-meta p span 文本 "作者：XXX"
    if (!info.author) {
      for (const span of $$('.book-meta p span, .book-meta span', doc)) {
        const t = (span.innerText || '').trim();
        const m = t.match(/^作者\s*[:：]\s*(.+)$/);
        if (m) { info.author = m[1].trim(); break; }
      }
    }
    // 4. 兜底:任意 authorarticle 链接
    if (!info.author) {
      const aa = $('a[href*="/authorarticle/"]', doc);
      if (aa) info.author = (aa.innerText || '').trim();
    }
    // 标签 / 分类 / 简介 / 状态
    info.tags = meta('meta[property="og:novel:tags"]') || meta('meta[name="tags"]');
    info.category = meta('meta[property="og:novel:category"]') || meta('meta[name="cat"]');
    info.description = meta('meta[property="og:description"]') || meta('meta[name="description"]');
    info.status = meta('meta[property="og:novel:status"]');
    // 标签页可能在 DOM 中: .book-label a / .tag-list a 等
    if (!info.tags) {
      const tagAs = $$('.book-label a, .tag-list a, .tags a, .book-tags a', doc);
      if (tagAs.length) info.tags = tagAs.map(a => (a.innerText || '').trim()).filter(Boolean).join(' ');
    }
    return info;
  }
  async function linovelibParseDetail(doc, pageUrl) {
    const m = String(pageUrl).match(/\/novel\/(\d+)/);
    if (!m) return null;
    const novelId = m[1];
    const h1 = $('h1', doc);
    // v4.9.208-fix:书名优先取导航/面包屑的目录链接(章节页 h1 是章节标题如「插图」,只有详情页 h1 才等于书名)
    const title = linovelibNovelTitle(doc) || (h1 ? (h1.innerText || '').trim() : '');
    let info = linovelibExtractBookInfo(doc);
    let coverUrl = '';
    const cimg = $('.book-img img, .book-detail img[src*="/files/article/image/"]', doc);
    if (cimg) coverUrl = normUrl(cimg.getAttribute('src') || cimg.currentSrc);
    let sections = linovelibParseCatalog(doc, novelId);
    // 当前页缺章节列表或封面或作者 → 补抓另一页(详情页/目录页)
    const needDetail = !info.author || !coverUrl;
    const needCatalog = !sections.length;
    if (needDetail || needCatalog) {
      const origin = location.origin;
      const tasks = [];
      if (needDetail) tasks.push(linovelibFetchText(origin + '/novel/' + novelId + '.html').then(html => {
        if (html) {
          const ddoc = new DOMParser().parseFromString(html, 'text/html');
          const dInfo = linovelibExtractBookInfo(ddoc);
          if (dInfo.author) info.author = dInfo.author;
          if (dInfo.tags && !info.tags) info.tags = dInfo.tags;
          if (dInfo.description && !info.description) info.description = dInfo.description;
          if (dInfo.category && !info.category) info.category = dInfo.category;
          if (dInfo.status && !info.status) info.status = dInfo.status;
          if (!coverUrl) {
            const ci = $('.book-img img, .book-detail img[src*="/files/article/image/"]', ddoc);
            if (ci) coverUrl = normUrl(ci.getAttribute('src') || ci.currentSrc);
          }
        }
      }));
      if (needCatalog) tasks.push(linovelibFetchText(origin + '/novel/' + novelId + '/catalog').then(html => {
        if (html) sections = linovelibParseCatalog(new DOMParser().parseFromString(html, 'text/html'), novelId);
      }));
      await Promise.all(tasks);
    }
    return {
      novelId, title,
      author: info.author,
      tags: info.tags,
      description: info.description,
      status: info.status,
      category: info.category,
      coverUrl, sections,
      fetchedAt: Date.now()
    };
  }
  // 判断元素是否为站点 CSS 隐藏的诱饵段落(前端页面用 position:absolute + transform:scale(0) 隐藏,
  // innerText 仍会包含其文本,需按计算样式跳过,避免依赖"去重"才能还原顺序)
  function isLinovelibDecoy(el) {
    if (!el) return false;
    const win = el.ownerDocument ? (el.ownerDocument.defaultView || window) : window; // 兼容 iframe 内元素(用元素自身窗口计算样式)
    if (!win.getComputedStyle) return false;
    const cs = win.getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') return true; // display:none 克隆诱饵
    const tr = (cs.transform || '').trim();
    if (!tr || tr === 'none') return false;
    const m = tr.match(/matrix\(([^)]+)\)/);
    if (m) {
      const v = m[1].split(',').map(s => parseFloat(s.trim()));
      // scaleX/scaleY 任一为 0 即视为诱饵
      if (v.length >= 6 && (v[0] === 0 || v[3] === 0)) return true;
    } else {
      return true; // 非 none 的 transform,保守视为诱饵
    }
    return false;
  }
  function linovelibParseChapter(doc, pageUrl) {
    // 注意:分页 URL 带页码后缀,如 /novel/3032/151118_2.html
    const m = String(pageUrl).match(/\/novel\/(\d+)\/(\d+)(?:_\d+)?\.html/);
    if (!m) return null;
    const novelId = m[1], chapterId = m[2];
    const h1 = $('h1', doc);
    /* v4.9.199:站点在第 2 页起的 h1 里带「(当前页/总页数)」标记(如「…异于常人(4/4)」),第 1 页没有。
       这是拿"站点页数"最便宜也最可靠的办法 —— 顺手记下来,抓完立刻就能和"抓到的页数"比,不用再问站点。 */
    const _h1raw = h1 ? (h1.innerText || '').trim() : '';
    const _hmk = _h1raw.match(/[（(]\s*(\d+)\s*\/\s*(\d+)\s*[）)]/);
    const siteTotal = _hmk ? parseInt(_hmk[2], 10) : null;
    const title = _h1raw.replace(/[（(]\s*\d+\s*\/\s*\d+\s*[）)]\s*$/, '').trim();
    const cc = $('#TextContent', doc);
    if (!cc) return null;
    const imgMap = new Map();
    const blocks = [];
    // 遍历 childNodes(含直接文本节点):部分章节正文直接写在容器文本节点里,子元素只是空壳 <p>/<br>
    for (const node of cc.childNodes) {
      if (node.nodeType === Node.TEXT_NODE) {
        const t = (node.nodeValue || '').trim();
        if (t) blocks.push({ type: 'p', html: '<p>' + escHtml(t) + '</p>' });
        continue;
      }
      if (node.nodeType !== Node.ELEMENT_NODE) continue;
      const el = node;
      const tag = el.tagName.toLowerCase();
      if (tag === 'br' || tag === 'hr') continue; // 独立 br/hr 只是分行装饰,忽略
      if (tag === 'div' && !(el.innerText || '').trim() && !el.querySelector('img')) continue; // 广告/空块
      if (el.classList && el.classList.contains('dag')) continue;
      if (isLinovelibDecoy(el)) continue; // 跳过被站点隐藏(scale(0))的诱饵段落
      for (const b of elementToBlocks(el, tag, imgMap)) {
        if (b.html && b.html.trim()) blocks.push({ type: b.type, html: b.html.trim() });
      }
    }
    const imgUrls = imgMapToUrls(imgMap);
    return { novelId, chapterId, title, blocks, imgUrls, textLen: (cc.innerText || '').trim().length, siteTotal: siteTotal };
  }
  // 仅用于抓取目录页/详情页元数据(fetch 同源带 cookie,GM 兜底);章节正文不走此函数(站点对 fetch/XHR 会返回乱序正文,正文走 iframe 方案)
  async function linovelibFetchText(url) {
    try {
      const r = await fetch(url, { credentials: 'include' });
      if (r.ok) return await r.text();
    } catch (e) {}
    return httpText(url);
  }
  function linovelibNextPageUrl(doc, novelId, chapterId) {
    // 用 a.href(浏览器按 iframe 自身 base 解析后的绝对地址)而非原始属性,避免相对链接被顶部页面 URL 错误解析
    const absHref = (a) => (typeof a.href === 'string' && a.href) ? a.href : (a.getAttribute('href') || '');
    const re = new RegExp('/novel/' + novelId + '/' + chapterId + '(?:_\\d+)?\\.html');
    for (const a of $$('.mlfy_page a', doc)) {
      const href = absHref(a);
      const text = (a.innerText || '').trim();
      if (re.test(href) && /下一页|下一頁/.test(text)) return normUrl(href);
    }
    // 兜底:直接找同章节的 _N 分页链接
    for (const a of $$('a[href*="/novel/' + novelId + '/' + chapterId + '_"]', doc)) {
      const href = absHref(a);
      if (new RegExp('/novel/' + novelId + '/' + chapterId + '_\\d+\\.html').test(href)) return normUrl(href);
    }
    return null;
  }
  // 哔哩轻小说对 fetch/XHR 会返回乱序正文;故改用 iframe 加载(真实浏览),等待注入
  // data-k 诱饵后按计算样式过滤隐藏诱饵(display:none / scale(0)),得到正确顺序正文。
  // 在隐藏 iframe 中加载 URL,轮询直到 #TextContent 就绪且注入 data-k 诱饵(页面稳定),超时 30s
  /* v4.9.193:限流节奏 —— 抓页面(这里)和「校验缺页」(GM_xhr 直连那条路)共用同一个名额池:
     最多同时 LN_FRAME_SLOTS 个,每个跑完再等 LN_PAGE_GAP_MS 才放下一个。
     想更快:调大 LN_FRAME_SLOTS(3 = 回到原脚本的并发数);想最保守:调成 1。
     整段关掉:把 LN_POLITE 改成 false(原函数体原样保留在 linovelibLoadPageInFrameRun 里)。 */
  const LN_POLITE = true;
  const LN_FRAME_SLOTS = 2;
  const LN_PAGE_GAP_MS = 1000;
  /* v4.9.201:整块「校验缺页」已按要求删除(LN_PROBE_GAP_MS 是它专属的间隔,一并去掉) */
  let _lnFrameBusy = 0;
  async function lnAcquireSlot(tag) {
    if (!LN_POLITE) return;
    for (let n = 0; n < 600; n++) {
      if (_lnFrameBusy < LN_FRAME_SLOTS) { _lnFrameBusy++; return; }
      await new Promise((r) => setTimeout(r, 250));
    }
    throw new Error('等待抓取空位超时(其他章节还在抓): ' + (tag || ''));
  }
