    let best = -1;
    for (const p of pats) { const k = html.indexOf(p, Math.max(0, from || 0)); if (k >= 0 && (best < 0 || k < best)) best = k; }
    if (best < 0) for (const p of pats) { const k = html.indexOf(p); if (k >= 0 && (best < 0 || k < best)) best = k; }
