        if (_cell && !e.target.closest('button, a') && _cell.hasAttribute('data-i')) { const _row = rows[+_cell.getAttribute('data-i')]; if (_row) bkDetailOpen(_row); return; }
        const _rb = e.target.closest('[data-act="read"]');
        if (_rb && _rb.hasAttribute('data-i')) { const _row = rows[+_rb.getAttribute('data-i')]; if (_row) { close(); openReader(_row.id).catch(err => log('✗ ' + err.message, 'err')); } return; }
        const _cb = e.target.closest('[data-act="chapters"]');
