    minimax: { name: 'MiniMax', short: 'MiniMax', base: 'https://api.minimax.io/v1', model: 'MiniMax-M2.7', priceIn: 2.1, priceOut: 8.4, note: 'MiniMax-M2.7 价(按 1USD≈7CNY 折算);M2.x 常开思考', console: 'https://platform.minimax.io/' },
    'minimax-cn': { name: 'MiniMax (CN)', short: 'MiniMax-CN', base: 'https://api.minimax.cn/v1', model: 'MiniMax-M2.7', priceIn: 2.1, priceOut: 8.4, note: 'MiniMax-M2.7 价参考(1USD≈7CNY);国内站以控制台为准', console: 'https://platform.minimaxi.com/' },
