  function estCostSuffix(c, inTok, outTok, mp) {
    if (aiDisplayMode(c) === 'price' && mp) {
      const cost = (inTok || 0) / 1e6 * (mp.priceIn || 0) + (outTok || 0) / 1e6 * (mp.priceOut || 0);
      if (cost > 0) return ' ≈ ' + fmtYuan(cost);
    }
    return '';
  }
  // v3.5.16:从响应 usage 解析缓存命中 token(各家字段不同,兼容取;找不到返回 0)
  function usageCacheHit(u) {
    if (!u) return 0;
    if (typeof u.prompt_cache_hit_tokens === 'number' && u.prompt_cache_hit_tokens > 0) return u.prompt_cache_hit_tokens; // DeepSeek
    const d = u.prompt_tokens_details;
    if (d && typeof d.cached_tokens === 'number' && d.cached_tokens > 0) return d.cached_tokens; // OpenAI/千问/智谱/MiniMax/豆包/Gemini兼容层
    if (typeof u.cached_tokens === 'number' && u.cached_tokens > 0) return u.cached_tokens;       // Kimi(顶层)
    const um = u.usage_metadata;
    if (um && typeof um.cached_content_token_count === 'number' && um.cached_content_token_count > 0) return um.cached_content_token_count; // Gemini 原生
    return 0;
  }
  // v3.5.16:实际消耗混合计价——命中 token 按缓存命中输入价、其余按标准输入价、输出按输出价。
  //   未设价(mp 为 null)或结果为 0 → 0;缓存价未填 → 按标准输入价计。
  function actCostOf(mp, inTok, hitTok, outTok) {
    if (!mp) return 0;
    const hit = hitTok || 0;
    const cache = typeof mp.priceCache === 'number' ? mp.priceCache : (mp.priceIn || 0);
    return ((Math.max(0, (inTok || 0) - hit)) * (mp.priceIn || 0) + hit * cache + (outTok || 0) * (mp.priceOut || 0)) / 1e6;
  }
  // v3.5.16:翻译完成句追加显示——token 模式追加「(命中 Y)」;price 模式且有价 → 再追加「 ≈ ¥xx」(按混合实际价)
  function hitCostSuffix(c, inTok, hitTok, outTok, mp) {
    const hitTxt = hitTok > 0 ? '(命中 ' + hitTok.toLocaleString() + ')' : '';
    if (aiDisplayMode(c) === 'price' && mp) {
      const cost = actCostOf(mp, inTok, hitTok, outTok);
      if (cost > 0) return hitTxt + ' ≈ ' + fmtYuan(cost);
    }
    return hitTxt;
  }
