          const poCus = c.prov && c.prov.custom;
          const legacyCus = (poCus && poCus.model) || (c.provider === 'custom' ? c.model : '');
          if (legacyCus && !(c.models.custom && c.models.custom.length)) {
            c.models.custom = [defaultModelDef(legacyCus)];
          }
          // 迁移旧数据:历史单 Key 归到当前服务商名下
          if (c.apiKey && !c.keys[c.provider]) c.keys[c.provider] = c.apiKey;
          // 当前服务商取对应的 Key(各服务商独立存 Key,互不串用)
          c.apiKey = c.keys[c.provider] || '';
