          cursor: 'never',
          width: { ideal: Math.max(800, Math.round(window.innerWidth * idealDpr)) },
          height: { ideal: Math.max(600, Math.round(window.innerHeight * idealDpr)) },
          frameRate: { ideal: 30 }
