      try { delete _paddle.engines[mid]; } catch (e) {}
      if (_paddle.engineModel === mid) { _paddle.engine = null; _paddle.loadingPromise = null; _paddle.engineModel = null; _paddle.available = null; _paddle.failReason = ''; }
