      try { if (!globalThis.__lnOcrHostWarned) { globalThis.__lnOcrHostWarned = 1; console.warn('[ln-port] 扩展侧引擎没接上,本轮按老路在本页建引擎(不影响功能):' + ((e && e.message) || e)); } } catch (e2) {}
