        const depOk = (dep) => findGlobalByShape(dep) != null;
        console.debug('[PaddleOCR] 初始化前全局状态(形状校验):ort=', depOk(deps[1]), ' fflate=', depOk(deps[0]), ' eSearchOCR=', depOk(deps[2]));
        if (!depOk(deps[0]) || !depOk(deps[1]) || !depOk(deps[2])) {
          if (!depOk(deps[0])) await requireRuntime(deps[0]);
          if (!depOk(deps[1])) await requireRuntime(deps[1]);
          if (!depOk(deps[2])) await requireRuntime(deps[2]);
          console.debug('[PaddleOCR] 注入后全局状态(形状校验):ort=', depOk(deps[1]), ' fflate=', depOk(deps[0]), ' eSearchOCR=', depOk(deps[2]));
        }
