        const busy = {};
        let ptr = 0, firstErr = null;
        const take = () => {
          while (ptr < todo.length) { const si = todo[ptr++]; if (!busy[si] && texts[si] === undefined) { busy[si] = true; return si; } }
          return -1;
        };
