  // OCR 预设栏 + 编辑器挂载(识别对照 / AI 设置两处复用;切换预设时整体替换面板节点避免监听叠加)
  function mountOcrNormUi(host, onChange) {
    if (!host) return;
    host.innerHTML = '<div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-bottom:4px;font-size:12px;color:#333">' +
      '<b style="color:#2f6f4f;font-size:12px">预设:</b>' +
      '<select id="ocr-presetsel" style="font-size:12px;border:1px solid #ccc;border-radius:4px;padding:1px 4px;color:#222"></select>' +
      '<button type="button" id="ocr-presetnew" title="把当前预设复制为新预设并切换过去" style="padding:1px 8px;font-size:11px;border:1px solid #2f6f4f;color:#2f6f4f;background:#fff;border-radius:4px;cursor:pointer">＋ 新建</button>' +
      '<button type="button" id="ocr-presetdel" title="删除当前预设(至少保留一套)" style="padding:1px 8px;font-size:11px;border:1px solid #2f6f4f;color:#2f6f4f;background:#fff;border-radius:4px;cursor:pointer">✕ 删除</button>' +
      '<span style="font-size:11px;color:#b06a2a">切换预设即刻生效于下方试算与重判</span></div>' +
      '<div class="esj-ocr-np" style="min-width:0"></div>';
    let selEl = host.querySelector('#ocr-presetsel');
    let panel = host.querySelector('.esj-ocr-np');
    const fillSel = () => {
      const cur = ocrPresetActive();
      selEl.innerHTML = ocrPresetList().map(p =>
        '<option value="' + escAttr(p.name) + '"' + (p.name === cur ? ' selected' : '') + '>' + escHtml(p.name) + (p.enabled ? '' : '(停用)') + ' · ' + p.count + '卡</option>').join('');
    };
    const renderPanel = () => {
      const np = document.createElement('div');
      np.className = 'esj-ocr-np';
      if (panel && panel.parentNode) panel.replaceWith(np);
      panel = np;
      renderOcrNormPanel(panel, onChange);
    };
    fillSel();
    renderPanel();
    selEl.addEventListener('change', () => { if (ocrPresetSwitch(selEl.value)) { fillSel(); renderPanel(); } });
    host.querySelector('#ocr-presetnew').addEventListener('click', () => {
      const name = window.prompt('新预设名称(将复制当前预设的内容并切换过去):');
      if (name == null) return;
      const r = ocrPresetNew(name);
      if (r && r.err) { alert(r.err); return; }
      fillSel(); renderPanel();
    });
    host.querySelector('#ocr-presetdel').addEventListener('click', () => {
      const cur = ocrPresetActive();
      if (!window.confirm('删除预设「' + cur + '」?')) return;
      const r = ocrPresetDelete(cur);
      if (r && r.err) { alert(r.err); return; }
      fillSel(); renderPanel();
    });
  }
  // v3.4.8:直引号 " 开闭交替归一(状态追踪,换行重置)——正则上下文判断无法处理「和"三见」这类情况
