      for (let k = 0; k < segs.length; k++) {
        const s = segs[k];
        if (s.type === 'common') commonRanges.push([s.refStart, s.refStart + s.text.length]);
        else if (s.type === 'missing') missingRanges.push([s.refStart, s.refStart + s.text.length]);
        else if (k > 0 && segs[k - 1].type === 'missing') replExtra.set(s.refStart, s.text); // 替换对:该份用 extra 替换 ref 内容
        else insExtra.set(s.refStart, s.text); // 独立插入:ref 无对应内容,该份多出
      }
      return { commonRanges, missingRanges, replExtra, insExtra };
