        const merged = mergeModelsInto(localModels[provSel.value] || [], ids);
        localModels[provSel.value] = merged.list;
        if (merged.added) { renderThinkingSelect(); renderCml(); }
        if (!mdlInput.value.trim() && ids.length) mdlInput.value = ids[0].id;
