  // —— 翻译自动术语表(本书·跨会话·自动增长;翻译生成,润色/语境翻译读取) ——
  async function getAutoTerms(novelId) { try { const m = await getMeta(novelId); return (m && m.termAuto) || {}; } catch (e) { return {}; } }
  // 翻译 sys 追加段:沿用已记住术语 + 请 AI 回传新术语(仅 cfg.termAuto 开启时调用)
  async function autoTermPart(novelId, text) {
    const map = await getAutoTerms(novelId);
    let manual = {};
    try { manual = ((await getTermTable(novelId)).name) || {}; } catch (e) {}
    const txt = String(text || '');
    const rawHits = [];
    for (const k of Object.keys(map)) {
      const v = map[k];
      if (!v || !v.tr || manual[k]) continue; // 手动固定优先,不与自动重复
      if (txt.indexOf(k) >= 0) rawHits.push({ key: k, val: v.tr });
    }
    const hits = trimTermEntries(rawHits, txt).map(e => e.key + '→' + e.val);
    let s = '';
    if (hits.length) s += '本书已沿用术语(原文出现这些原名且确指该人物/专名时,沿用表中译法以保持全书人名/专名一致;仅当其在此并非指称其人时按语义译;人名以部分/简称出现且确指同一人时沿用其风格,但输出形式必须与原文一致,禁止扩写为全名):' + hits.slice(0, 40).join(',') + '。';
    s += bpText('auto_term_return', BP_AUTO_RETURN_DEFAULT); // 回传指令可在 AI设置→内置提示词 覆盖
    return s;
  }
