  // v4.9.32:整表文本(固定译名 / 其他术语 / 自动术语分三部分;人工两段标注"只报告不自动改")——
  //   只在「提到术语表」的那一轮按需全传(平时仍只传命中的术语,省 token);上限 400 条 / 12000 字,超了标记截断
  async function termTableFullText(novelId, scope) {
    const sc = String(scope || 'all');
    let auto = {}, tb = null;
    try { auto = (await getAutoTerms(novelId)) || {}; } catch (e) {}
    try { tb = await getTermTable(novelId); } catch (e) {}
    const names = (tb && tb.name) || {}, words = (tb && tb.word) || {};
    const secName = [], secWord = [], secAuto = [];
    for (const k of Object.keys(names)) { const r = names[k]; const v = (r && typeof r === 'object') ? (r.tr || '') : r; if (k && v) secName.push(k + '→' + v); }
    for (const k of Object.keys(words)) { const r = words[k]; const v = (r && typeof r === 'object') ? (r.def || '') : r; if (k && v) secWord.push(k + '→' + v); }
    for (const k of Object.keys(auto)) { const v = auto[k] && auto[k].tr; if (k && v && !names[k]) secAuto.push(k + '→' + v); }
    const MAX_ITEMS = 400, MAX_CHARS = 12000;
    let text = '', count = 0, truncated = false;
    const push = (title, arr) => {
      if (!arr.length) return;
      text += '\n' + title + '(' + arr.length + '条):';
      for (const s of arr) {
        if (count >= MAX_ITEMS || text.length + s.length > MAX_CHARS) { truncated = true; return; }
        text += '\n' + s; count++;
      }
    };
    if (sc !== 'auto') {
      push('【固定译名 · 人工维护,权威,只报告问题、不要回传改动】', secName);
      push('【其他术语 · 人工维护,权威,只报告问题、不要回传改动】', secWord);
    }
    if (sc !== 'manual') push('【自动术语 · 程序自动积累,可删可改】', secAuto);
    return { text: text.replace(/^\n/, ''), count: count, truncated: truncated };
  }
  // v4.9.24:本书现行术语全量提示(人工固定译名优先 + 自动术语表;上限 40 条,长条目优先)——
  //   用于"追问轮输入是纯中文指令、termHint 命中不到任何术语"的场景:让模型看得到现行术语表,
  //   才能正确回传「修正/删除」,校验也才有依据(原名出现在给模型的材料里即算数)
  async function autoTermFullHint(novelId) {
    let auto = {}, manual = {};
    try { auto = (await getAutoTerms(novelId)) || {}; } catch (e) {}
    try { manual = ((await getTermTable(novelId)) || {}).name || {}; } catch (e) {}
    const pairs = [], seen = {};
    for (const k of Object.keys(manual || {})) {
      const raw = manual[k];
      const v = (raw && typeof raw === 'object') ? (raw.tr != null ? raw.tr : '') : raw;
      if (!k || !v || seen[k]) continue;
      seen[k] = 1; pairs.push({ k: k, v: String(v) });
    }
    for (const k of Object.keys(auto || {})) {
      const v = auto[k] && auto[k].tr;
      if (!k || !v || seen[k]) continue;
      seen[k] = 1; pairs.push({ k: k, v: String(v) });
    }
    if (!pairs.length) return '';
    pairs.sort((a, b) => String(b.k).length - String(a.k).length); // 长条目(更具体)优先展示
    return '本书现行术语表(人工固定译名优先;供你核对/统一译名,仍要按当前文本判断是否真的用得到):' + pairs.slice(0, 40).map(p => p.k + '→' + p.v).join(',') + '。';
  }
