      const text = blocksPlainText([srcBlocks[selIdx]]);
      if (!text.trim()) { setStatus('该段原文为空'); return; }
      // 语言按原文检测(记录里的 blocks 是译文,不能拿来做语言判断)
      const srcLang = detectLang(text) || detectLang(blocksPlainText(srcBlocks)) || '';
      speakText(text, srcLang, setStatus);
