            const len = (wn.nodeValue || '').length;
            if (!pos && wn.parentNode && wn.parentNode.classList && wn.parentNode.classList.contains('rd-anno')) { acc += len; continue; }
            tns.push({ node: wn, off: acc });
            acc += len;
