        if (e.target.closest('#rd-aichat-toolbtn')) return; // v4.9.140:工具设置按钮同上
        if (e.target.closest('#rd-aichat-modelbtn') || e.target.closest('#rd-aichat-modelpick')) return; // v4.9.153:模型选择栏不参与"整行切换开关"
