        e.target.title = (nx === 'strict' ? '剧透:严格 —— 当前章之后的检索结果会被丢弃' : (nx === 'open' ? '剧透:开放 —— 不拦不遮,可提前查阅后续章节' : '剧透:黑幕 —— 参考了后续章节的回答会被盖住,点一下才显示'));
