          const byRange = (segE != null && segE >= seg); // 区间写法(否则按半径展开)
          let s0 = byRange ? (seg - 1) : Math.max(0, seg - 1 - rad);
          let e0 = byRange ? Math.min(total, segE) : Math.min(total, seg + rad);
          let clampNote = '', oobNote = '';
          // v4.9.160:起点就越界(模型猜的段号超过本章长度)—— 旧版只是夹到"最后一段",于是只回 1 段无关内容
          //   (实测:第 18 章只有 71 段,模型要 90-115，只回了第 71 段那句"感谢各位阅读。"),头部还写着"共 1 段",那一轮等于白花。
          //   现改成:改给本章最后若干段 + 把真实段数讲清楚,让它下一轮能按实际段数调。
          if (total > 0 && seg > total) {
            s0 = Math.max(0, total - Math.max(10, Math.min(30, rad)));
            e0 = total;
            oobNote = '⚠ 你要的是第 ' + seg + ' 段' + (segE != null ? ('–' + segE + ' 段') : '') + ',但**本章只有 ' + total + ' 段** —— 已改给你最后 ' + (e0 - s0) + ' 段(第 ' + (s0 + 1) + '–' + e0 + ' 段)。要读别处请按实际段数再调;某章有多少段也可以先用 list_chapters 查(它每行末尾标着 [N段])。';
          } else if (byRange && segE > total) {
            oobNote = '⚠ 本章到第 ' + total + ' 段为止(你要到第 ' + segE + ' 段,已给到章末)。';
          } else if (s0 >= total) s0 = Math.max(0, total - 1);
          if (e0 - s0 > RD_RA_MAX) { e0 = s0 + RD_RA_MAX; clampNote = ';已达单次上限 ' + RD_RA_MAX + ' 段 —— 想看后面就再调一次,从第 ' + (e0 + 1) + ' 段接着读'; }
          const out = [];
          for (let i = s0; i < e0; i++) {
            out.push('【第' + (i + 1) + '段】\n原文: ' + (or[i] ? blocksToText([or[i]]) : '(无)') + '\n译文: ' + (tr[i] ? blocksToText([tr[i]]) : '(尚无译文)'));
          }
          // v4.9.167:头行里 `共 N 段` 的口径与 search_book 统一 = 本章总段数(此前它写的是"本次读取了几段",
          //   实测被模型读成"本章一共 80 段" —— 同一措辞两种意思必出事)。本次读了多少,区间 `第 A–B 段` 已经写明,不必再计一次。
          const _head = '【第 ' + ci + ' 章' + (ch.title ? ('「' + ch.title + '」') : '') + ' 第 ' + (s0 + 1) + '–' + e0 + ' 段(本章共 ' + total + ' 段' + clampNote + ')】';
