          const _chNow = (st.chapters && st.chapters[st.chIdx]) || {};
          const _ctxHead = '\n\n【当前章节上下文 —— 第 ' + (st.chIdx + 1) + ' 章(目录序号 ' + (st.chIdx + 1) + ')' + (_chNow.title ? ('「' + _chNow.title + '」') : '') + ';本章之前的章都已读过,' + (rdSpoilerMode() === 'strict' ? '「之后的章」不允许查阅' : '「之后的章」也可以查阅') + '】\n'; // v4.9.143:非严格档统一为"也可以查阅"(与开放一致,不暴露遮罩机制)
          const ctxText = (ctx ? (_ctxHead + ctx) : (_chNow.title ? (_ctxHead.trim() + '\n(本章正文未取样:需要时可用 read_around 读当前章)') : ''))
