            let _mdlCap = 0;
            try { const _d = (typeof modelDefOf === 'function') ? modelDefOf(cfg, cfg.provider, cfg.model) : null; if (_d && _d.maxTokens > 0) _mdlCap = _d.maxTokens; } catch (e) {}
            const _mtSet = Math.max(2048, Number(cfg.mtTr) || 4096); // AI 设置「翻译/润色 MAX TOKEN」(下限 2048)
            const b = { model: cfg.model, messages: msgs, max_tokens: (_mdlCap > 0 ? Math.min(_mdlCap, _mtSet) : _mtSet), stream: true };   /* 1.1.65:原来写死 2048 —— 回答长、或思考档位吃掉输出额度时会被拦腰截断;现在跟 AI 设置的 MAX TOKEN */
