          const stripToolLines = (s) => String(s == null ? '' : s).split('\n').filter(l => !/\[\[?\s*TOOL/i.test(l)).join('\n').replace(/\n{3,}/g, '\n\n').trim(); // v4.9.138:单方括号的调用行也剥掉
