      const total = rdSysFontFiltered.length;
      const pages = Math.max(1, Math.ceil(total / RD_SYS_FONT_PER_PAGE));
      if (rdSysFontPage >= pages) rdSysFontPage = pages - 1;
      const start = rdSysFontPage * RD_SYS_FONT_PER_PAGE;
      const end = Math.min(start + RD_SYS_FONT_PER_PAGE, total);
