      const h3 = document.createElement('h3');
      h3.textContent = '标注 · ' + (q ? ('原文「' + (q.length > 28 ? q.slice(0, 28) + '…' : q) + '」(全书 ' + items.length + ' 处)') : ('全书 ' + items.length + ' 条'));
      dlg.appendChild(h3);
